// generated by swi-typespec-lab

const baseUrl = globalThis.BASE_URL ?? "http://127.0.0.1:4000";

export async function get(id) {
  const response = await fetch(baseUrl + `/users/${encodeURIComponent(id)}`, { method: "get" });
  if (!response.ok) throw new Error("HTTP " + response.status);
  return response.json();
}
